  let rows;try{rows=parseCsv(String(req.body||''));}catch(error){return res.status(422).json({error:error.message});}if(!rows.length)return res.status(422).json({error:'The CSV file is empty.'});const header=rows.shift().map(value=>value.toLowerCase());const required=['email','displayname','category','services','location','startingprice','currency'];const index=Object.fromEntries(required.map(key=>[key,header.indexOf(key)]));if(required.some(key=>index[key]<0))return res.status(422).json({error:`CSV needs these columns: ${required.join(', ')}`});if(rows.length>300)return res.status(413).json({error:'Upload at most 300 seller rows at a time.'});let imported=0;const skipped=[];const categories=['Design','Development','Writing','Marketing','Video & Audio','Consulting','Other'];
  for(let i=0;i<rows.length;i++){const row=rows[i],value=key=>row[index[key]]||'',email=value('email').toLowerCase(),category=value('category'),currency=value('currency').toUpperCase(),displayName=value('displayname'),services=value('services'),location=value('location');try{if(!email.includes('@')||displayName.length<2||displayName.length>80||services.length<20||services.length>1200||location.length>80||!categories.includes(category)||!['KES','USDT'].includes(currency))throw new Error('invalid profile fields');const account=await User.findOne({email});if(!account)throw new Error('member account not found');const startingPriceMinor=amountFromForm(value('startingprice'),currency);await SellerProfile.findOneAndUpdate({userId:account._id},{$set:{userId:account._id,displayName,category,services,location,startingPriceMinor,currency,published:true,approvalStatus:'pending',updatedAt:new Date()},$unset:{approvedBy:1,approvedAt:1}},{upsert:true,runValidators:true,setDefaultsOnInsert:true});imported++;}catch(error){skipped.push({row:i+2,reason:error.message});}}
  await Audit.create({adminId:req.session.user.id,action:'seller_csv_imported',details:{imported,skipped:skipped.length}});res.json({imported,skipped:skipped.slice(0,30)});
