app.post('/admin/deal/:id/confirm',signedIn,adminOnly,checkCsrf,async(req,res)=>{const d=await Deal.findOne({publicId:req.params.id,status:'payment_review'});if(!d)return res.status(404).send('Payment not pending review.');const reference=/^(?:XW-[A-Z0-9]{9}|[A-Z0-9]{12})$/.test(String(d.paymentRef||''))?d.paymentRef:makePaymentReference(),receipt=String(req.body.receipt||'').trim().slice(0,120),note=String(req.body.note||'').trim().slice(0,1000),now=new Date();d.status='funded';d.depositedAt=now;d.paymentRef=reference;d.paymentMethod=d.currency==='KES'?'mpesa':'crypto';if(d.currency==='KES'&&receipt)d.mpesaReceipt=receipt;d.updatedAt=now;await d.save();const paymentUpdate={status:'confirmed',manualReviewedBy:req.session.user.id,manualReviewedAt:now,manualNote:note};if(receipt)paymentUpdate.providerReceipt=receipt;await PaymentIntent.updateMany({dealId:d._id,status:{$in:['pending','confirmed']}},{$set:paymentUpdate});await Audit.create({adminId:req.session.user.id,dealId:d._id,action:'deposit_confirmed_manually',details:{reference,receipt,note,network:d.cryptoNetwork}});res.redirect('/admin');});
