app.post('/admin/kiosk/:reference/complete',signedIn,adminOnly,checkCsrf,async(req,res)=>{const order=await ExchangeOrder.findOneAndUpdate({reference:req.params.reference,status:'payment_received'},{$set:{status:'completed',completedAt:new Date(),updatedAt:new Date()}},{new:true});if(!order)return res.status(409).send('This order is not ready to be completed.');await Audit.create({adminId:req.session.user.id,action:'kiosk_order_completed',details:{reference:order.reference}});res.redirect('/admin#kiosk-orders');});
app.post('/admin/kiosk/:reference/cancel',signedIn,adminOnly,checkCsrf,async(req,res)=>{const order=await ExchangeOrder.findOneAndUpdate({reference:req.params.reference,status:'awaiting_payment'},{$set:{status:'cancelled',updatedAt:new Date()}},{new:true});if(!order)return res.status(409).send('Only an order awaiting payment can be cancelled.');await Audit.create({adminId:req.session.user.id,action:'kiosk_order_cancelled',details:{reference:order.reference}});res.redirect('/admin#kiosk-orders');});
app.post('/admin/deal/:id/resolve',signedIn,adminOnly,checkCsrf,async(req,res)=>{const resolution=String(req.body.resolution),reference=String(req.body.reference||'').trim().slice(0,120);if(!['completed','refunded'].includes(resolution))return res.status(422).send('Invalid resolution.');const d=await Deal.findOne({publicId:req.params.id,status:{$in:['release_requested','refund_requested']}});if(!d)return res.status(409).send('A deal can be recorded as released only after buyer release, or refunded after both parties agree.');if(!reference)return res.status(422).send('Enter the payout or refund transaction reference after processing it.');if(resolution==='completed'&&d.status!=='release_requested')return res.status(409).send('The buyer must request release before payout can be recorded.');if(resolution==='refunded'&&(d.status!=='refund_requested'||!d.refundAgreedBy.some(item=>item.role==='buyer')||!d.refundAgreedBy.some(item=>item.role==='seller')))return res.status(409).send('Both buyer and seller must agree to the refund before it can be recorded.');const now=new Date();d.status=resolution;d.updatedAt=now;d.closedAt=now;d.payoutReference=reference;if(resolution==='completed')d.releasedAt=now;else d.refundedAt=now;await d.save();await Audit.create({adminId:req.session.user.id,dealId:d._id,action:resolution==='completed'?'release_recorded':'refund_recorded',details:{reference,note:String(req.body.note||'').slice(0,1000)}});res.redirect('/admin');});
app.post('/admin/report/:id',signedIn,adminOnly,checkCsrf,async(req,res)=>{const status=['reviewed','dismissed','substantiated','unsubstantiated'].includes(String(req.body.status))?String(req.body.status):'reviewed',publicSummary=String(req.body.publicSummary||'').trim().slice(0,500);if(status==='substantiated'&&publicSummary.length<20)return res.status(422).send('Add a brief public summary of the substantiated conduct before publishing.');const report=await SafetyReport.findByIdAndUpdate(req.params.id,{$set:{status,reviewedAt:new Date(),publicSummary:status==='substantiated'?publicSummary:''}},{new:true});if(!report)return res.status(404).send('Report not found.');await Audit.create({adminId:req.session.user.id,action:status==='substantiated'?'safety_report_substantiated':status==='unsubstantiated'?'safety_report_unsubstantiated':status==='dismissed'?'safety_report_dismissed':'safety_report_reviewed',details:{reportId:req.params.id}});res.redirect('/admin#safety');});
app.post('/admin/user/:id',signedIn,adminOnly,checkCsrf,async(req,res)=>{const status=['active','suspended','closed'].includes(req.body.status)?req.body.status:'active';const account=await User.findById(req.params.id);if(!account)return res.status(404).send('Account not found.');if(String(account.email||'').trim().toLowerCase()===String(process.env.ADMIN_EMAIL||'').trim().toLowerCase()&&status!=='active')return res.status(422).send('The XWADDA owner account must remain active here.');account.status=status;account.role=String(account.email||'').trim().toLowerCase()===String(process.env.ADMIN_EMAIL||'').trim().toLowerCase()?'admin':'user';await account.save();await Audit.create({adminId:req.session.user.id,action:'account_updated',details:{userId:req.params.id,status}});res.redirect('/admin');});

