app.post('/api/mpesa/prompt',signedIn,checkCsrf,async(req,res)=>{
  const accountId=String(process.env.HASHPAY_ACCOUNT_ID||'').trim(),apiKey=String(process.env.MPESA_API_KEY||process.env.HASHPAY_API_KEY||'').trim();
  if(!accountId)return res.status(503).json({error:'M-Pesa collection account is missing. Set HASHPAY_ACCOUNT_ID in the deployment environment.'});
  if(!apiKey)return res.status(503).json({error:'M-Pesa API key is missing. Set MPESA_API_KEY in the deployment environment.'});
  const dealId=String(req.body.deal||''),orderRef=String(req.body.order||'');let deal=null,order=null,user=null,amountMinor=0,ref='';
  if(dealId){deal=await Deal.findOne({publicId:dealId,buyerId:req.session.user.id,status:{$in:['awaiting_payment','payment_review']}});if(!deal||deal.currency!=='KES')return res.status(409).json({error:'This deal is not available for an M-Pesa deposit.'});amountMinor=buyerDueMinor(deal);ref=deal.paymentRef;user=await User.findById(req.session.user.id).select('wallet').lean();}
  else if(orderRef){order=await ExchangeOrder.findOne({reference:orderRef,userId:req.session.user.id,direction:'buy',status:'awaiting_payment'});if(!order)return res.status(409).json({error:'This kiosk order is not available for an M-Pesa payment.'});amountMinor=Math.round(order.kesAmount*100);ref=order.reference;user=await User.findById(req.session.user.id).select('wallet').lean();}
  else return res.status(422).json({error:'Choose a valid deal or order.'});
  if(amountMinor%100!==0)return res.status(422).json({error:'M-Pesa payments must be a whole KES amount. Update the deal or order amount.'});
  let phoneInput=String(req.body.phone||'').trim();if(!phoneInput){try{phoneInput=decryptPrivate(user?.wallet?.mpesaPhoneEnc)}catch{}}
  const msisdn=normalizeKenyanPhone(phoneInput);if(!msisdn)return res.status(422).json({error:'Enter a valid Kenyan M-Pesa number to receive the payment prompt.'});
  let intent=deal?await PaymentIntent.findOne({dealId:deal._id,provider:'hashpay'}).sort({createdAt:-1}):await PaymentIntent.findOne({exchangeOrderId:order._id,provider:'hashpay'}).sort({createdAt:-1});
  if(intent?.status==='confirmed')return res.status(409).json({error:'Payment has already been received. Check the order status before trying again.'});
  if(intent?.providerPayload?.stkInitiated)return res.json({intent:String(intent._id),reference:intent.providerReference,phone:phoneInput,alreadySent:true});
  if(!intent){if(deal&&deal.status!=='awaiting_payment'&&deal.status!=='payment_review')return res.status(409).json({error:'This deal is not ready for payment.'});intent=await PaymentIntent.create({...(deal?{dealId:deal._id}:{exchangeOrderId:order._id}),provider:'hashpay',providerReference:ref&&/^(?:XW-[A-Z0-9]{9}|[A-Z0-9]{12})$/.test(ref)?ref:makePaymentReference(),amountMinor,currency:'KES'});}else if(intent.status==='failed'||intent.status==='exception'){intent.status='pending';intent.providerReference=makePaymentReference();intent.providerTransactionId=undefined;intent.providerReceipt=undefined;intent.providerPayload=undefined;intent.amountMinor=amountMinor;await intent.save();}
  const reference=intent.providerReference;
  let upstream,payload;try{upstream=await fetch('https://api.hashback.co.ke/initiatestk',{method:'POST',headers:{'content-type':'application/json',accept:'application/json'},body:JSON.stringify({api_key:apiKey,account_id:accountId,amount:String(amountMinor/100),msisdn,reference}),signal:AbortSignal.timeout(12000)});const responseText=await upstream.text();try{payload=JSON.parse(responseText)}catch{payload={}}}catch(error){console.error('[mpesa-prompt] Provider request failed:',error.name||'network error');return res.status(502).json({error:'The M-Pesa service could not be reached. Check the deployment logs and try again shortly.'});}
  const checkoutId=String(payload.checkout_id||payload.CheckoutRequestID||'');if(!upstream.ok||!(payload.success===true||String(payload.ResponseCode)==='0')||!checkoutId){console.warn('[mpesa-prompt] Provider rejected the prompt:',{httpStatus:upstream.status,code:String(payload.error?.code||payload.errorCode||payload.ResponseCode||payload.code||'unknown').slice(0,80)});intent.status='failed';intent.providerPayload={promptRejected:true,at:new Date(),providerHttpStatus:upstream.status,providerErrorCode:String(payload.error?.code||payload.errorCode||payload.ResponseCode||payload.code||'').slice(0,80)};await intent.save();return res.status(502).json({error:'The M-Pesa service rejected the prompt. Check that the account is active, the API key and account ID match, and the number is eligible for live or test payments.'});}
  intent.providerTransactionId=checkoutId;intent.providerPayload={stkInitiated:true,checkoutId,initiatedAt:new Date()};await intent.save();
  if(deal){deal.paymentRef=reference;deal.paymentMethod='mpesa';deal.status='payment_review';deal.updatedAt=new Date();await deal.save();}else if(order){order.paymentRef=reference;order.updatedAt=new Date();await order.save();}
  res.json({intent:String(intent._id),reference,phone:phoneInput,alreadySent:false});
});
